const STAGES=[["Siap-siap",["m1","m8"]],["Siapin berkas",["m2","m6"]],["Mulai melamar",["m3"]],["Hadapi seleksi",["m4","m5","m9"]],["Nilai tawaran",["m7"]]];
const M=Object.fromEntries(MODS.map(m=>[m.id,m]));
const G=(m,k)=>{try{return JSON.parse(localStorage.getItem("ks_"+m+"_"+k))}catch(e){return null}};
function prog(){const r={},cl=a=>Math.max(0,Math.min(1,a||0));
 const ck1=G("m1","ck")||[],st1=G("m1","st")||[];r.m1=cl(ck1.length/13*.6+st1.length/5*.4);
 const cv=G("m2","cv")||{},ck2=G("m2","ck")||[];r.m2=cl(ck2.length/12*.5+Object.values(cv).filter(v=>String(v).trim()).length/10*.5);
 const apps=G("m3","trk")||[];r.m3=cl(apps.length/5);
 const tk=G("m4","tk")||[],dr=G("m4","dr")||{};r.m4=cl(tk.length/10*.6+Object.values(dr).filter(v=>v=="ok").length/12*.4);
 const stor=(G("m5","stories")||[]).filter(s=>s&&[s.s,s.t,s.a,s.r].every(x=>String(x||"").trim())).length;r.m5=cl(stor/3);
 const mv=G("m6","mv")||{};r.m6=cl(Object.values(mv).filter(v=>String(v).trim()).length/6);
 const sd=G("m7","sd")||{},sst=G("m7","sst")||0;r.m7=cl(sst/3*.7+((sd.ck||[]).length/6)*.3);
 const c8=Object.values(G("m8","ck8")||{}).filter(Boolean).length;r.m8=cl(c8/27);
 const qa=G("m9","qa9")||{},hk=G("m9","hk9")||[];const an=Object.values(qa).reduce((a,x)=>a+(x?x.filter(v=>v!==null&&v!==undefined).length:0),0);r.m9=cl(an/14*.6+hk.length/8*.4);
 r.all=MODS.reduce((a,m)=>a+r[m.id],0)/MODS.length;r.apps=apps.length;r.c8=c8;r.stor=stor;r.idt=G("m4","idt");return r}
