window.__toast=t=>{const e=$("#kstoast");e.textContent=t;e.classList.add("on");clearTimeout(e._t);e._t=setTimeout(()=>e.classList.remove("on"),2600);Owi.say(t,null,2600,true)};
window.__boom=()=>{const f=document.createElement("div");f.style.cssText="position:fixed;inset:0;pointer-events:none;overflow:hidden;z-index:95";document.body.appendChild(f);for(let i=0;i<54;i++){const s=document.createElement("i");s.style.cssText=`position:absolute;left:${Math.random()*100}%;top:-20px;width:9px;height:14px;border-radius:2px;background:${["#D6AE65","#A9BDAA","#F7F3EA","#2E4A73"][i%4]};animation:dn ${2+Math.random()*2}s ease-in forwards`;f.appendChild(s)}setTimeout(()=>f.remove(),4500);Owi.celebrate()};

