 $("#krs").onclick=()=>{try{const o=JSON.parse($("#kbi").value);const ks=Object.keys(o).filter(k=>k.startsWith("ks_"));if(!ks.length)throw 0;ks.forEach(k=>localStorage.setItem(k,o[k]));__toast("Data dipulihkan. Memuat ulang…");setTimeout(()=>location.reload(),900)}catch(e){__toast("Kode nggak valid. Cek lagi tempelannya.")}};
