const Owi={cl:0,lastClick:0,idle:0,say(t,pose,ms,quiet){const b=$("#dbub");if(!b)return;b.textContent=t;b.classList.add("on");clearTimeout(b._t);b._t=setTimeout(()=>b.classList.remove("on"),ms||3000);const o=$("#dowi .owi");if(pose&&o&&!Owi.asleep){o.dataset.pose=pose;clearTimeout(o._p);o._p=setTimeout(()=>{if(!Owi.asleep)o.dataset.pose="idle"},ms||3000)}},
 celebrate(){const o=$("#dowi .owi");if(!o)return;o.dataset.pose="celebrate";clearTimeout(o._p);o._p=setTimeout(()=>o.dataset.pose="idle",3200)},
 react(el,quiet){el.classList.remove("hop");void el.offsetWidth;el.classList.add("hop");setTimeout(()=>el.classList.remove("hop"),700);const r=el.getBoundingClientRect(),cx=r.left+r.width/2;
  for(let i=0;i<5;i++){const h=document.createElement("div");h.className="ksht";h.textContent="♥";h.style.left=(cx-10+Math.random()*20)+"px";h.style.top=(r.top+r.height*.3)+"px";h.style.setProperty("--x",(Math.random()*60-30)+"px");h.style.animationDelay=i*.07+"s";document.body.appendChild(h);setTimeout(()=>h.remove(),1500)}
  const now=Date.now();Owi.cl=now-Owi.lastClick<1200?Owi.cl+1:1;Owi.lastClick=now;let t=LINES[Math.floor(Math.random()*LINES.length)];
  if(Owi.cl==4){t="Aduh, geli! Hahaha. Udah ah!";el.dataset.pose="wow"}if(Owi.cl>=7){t=JOKES[Math.floor(Math.random()*JOKES.length)];el.dataset.pose="celebrate";Owi.cl=0}
  if(Owi.asleep)Owi.wake();const b=document.createElement("div");b.className="ksbub2";b.textContent=t;b.style.left=cx+"px";b.style.top=(r.top-4)+"px";document.body.appendChild(b);setTimeout(()=>b.remove(),2500);
  if(el.dataset.pose=="wow"||el.dataset.pose=="celebrate"){clearTimeout(el._p);el._p=setTimeout(()=>{if(el.closest("#plowi"))return;el.dataset.pose=el.closest("#dowi")?"idle":(el.dataset._p||"idle")},2200)}},
 asleep:0,wake(){Owi.asleep=0;const o=$("#dowi .owi");o.dataset.pose="wow";setTimeout(()=>o.dataset.pose="idle",900);Owi.say("Hoam... eh, Lo balik! Gua nggak tidur kok.","wow",2500)},
 sleep(){if(Owi.asleep)return;Owi.asleep=1;const o=$("#dowi .owi");o.dataset.pose="sleep";$("#dbub").classList.remove("on")}};
