const QA=[["Mulai dari mana?",()=>{const n=nextMod(prog());return n?`Menurut progres Lo, lanjut ke <b>${M[n].no} ${M[n].n}</b>. ${M[n].tip}<br><a data-go="${n}">Buka modul →</a>`:"Progres Lo sudah bagus semua! Lakukan review mingguan di Career Checklist.<br><a data-go=\"m8\">Buka Career Checklist →</a>"}],["Apa itu STAR?",()=>"STAR itu rumus cerita: <b>S</b>ituation (konteks), <b>T</b>ask (tugas Lo), <b>A</b>ction (yang Lo lakukan), <b>R</b>esult (hasilnya). Gunanya buat jawab “ceritakan saat Lo…”.<br><a data-go=\"m5\">Latihan di STAR Workbook →</a>"],["Data Lo disimpan di mana?",()=>"Di browser Lo sendiri, nggak dikirim ke server. Biar aman pindah perangkat, simpan kode cadangan.<br><a data-go=\"data\">Ke Data & Cadangan →</a>"],["CV itu berapa halaman?",()=>"Untuk fresh graduate biasanya 1 halaman cukup. Boleh 2 kalau pengalaman banyak dan relevan. Ini panduan umum.<br><a data-go=\"m2\">Buka CV Builder →</a>"],["Gua gugup interview",()=>"Wajar banget. Coba: riset perusahaan, latih jawaban keras-keras pakai timer, siapkan 3 cerita STAR, dan tarik napas 4-4-4 sebelum masuk.<br><a data-go=\"m4\">Buka Interview Master →</a>"],["Psikotes ini resmi?",()=>"Bukan ya. Itu latihan buat kenalan format, bukan tes psikologi resmi, dan nggak memprediksi hasil tes asli.<br><a data-go=\"m9\">Lihat Psikotes Siap →</a>"],["Kapan follow-up lamaran?",()=>"Kebiasaan umum sekitar 5–7 hari kerja setelah melamar. Ada templatenya, tinggal salin.<br><a data-go=\"m6\">Buka Email Templates →</a>"],["Boleh nego gaji?",()=>"Nego yang sopan dan berdasar riset umumnya wajar, tapi hasilnya nggak bisa dijamin. Siapkan datanya dulu.<br><a data-go=\"m7\">Buka Salary Guide →</a>"],["Ceritain lelucon!",()=>JOKES[Math.floor(Math.random()*JOKES.length)]+" Hehe 🦉"],["Cara pakai dashboard ini?",()=>"Gampang: 1) Mulai dari Beranda, 2) pilih modul di sidebar, 3) isi dan centang. Semua tersimpan otomatis. Cari apa pun lewat kotak pencarian di atas."]];
